const products=[
{id:'instant-coffee',name:'Premium Instant Coffee',cat:'coffee',desc:'Premium Instant Coffee (In different flavors).',variant:'Flavor selection to be confirmed'},
{id:'ctc-tea',name:'Strong Premium CTC Tea',cat:'tea',desc:'Strong Premium CTC Tea.',variant:'Pack sizes to be confirmed'},
{id:'mustard-oil',name:'Cold Pressed Mustard Oil',cat:'edible-oils',desc:'Premium Cold Pressed Mustard Oil. Locally manufactured.',variant:'Bottle sizes to be confirmed'},
{id:'blend-coffee',name:'Arabica + Robusta Blend',cat:'coffee',desc:'Blended Coffee (Arabica + Robusta).',variant:'Pack sizes to be confirmed'},
{id:'ctc-blend',name:'Premium CTC Blend',cat:'tea',desc:'Premium CTC Blend.',variant:'Pack sizes to be confirmed'},
{id:'masala-tea',name:'Premium Masala Tea',cat:'tea',desc:'Premium Masala Tea.',variant:'Pack sizes to be confirmed'},
{id:'green-tea',name:'Green Tea',cat:'tea',desc:'Green Tea.',variant:'Pack sizes to be confirmed'},
{id:'cappuccino',name:'Cappuccino Premix',cat:'coffee',desc:'Cappuccino Premix.',variant:'Pack sizes to be confirmed'}];
const images={coffee:'https://images.unsplash.com/photo-1447933601403-0c6688de566e?auto=format&fit=crop&w=1000&q=85',tea:'https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=1000&q=85',oil:'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?auto=format&fit=crop&w=1000&q=85',story:'https://images.unsplash.com/photo-1472396961693-142e6e269027?auto=format&fit=crop&w=1100&q=85'};
const names={'coffee':'Coffee','tea':'Tea','edible-oils':'Edible oils'};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let cart=read('kedarmart-cart',{}),wishlist=read('kedarmart-wishlist',[]);
const app=document.querySelector('#app');
function save(){localStorage.setItem('kedarmart-cart',JSON.stringify(cart));localStorage.setItem('kedarmart-wishlist',JSON.stringify(wishlist));document.querySelector('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function art(p){return `<div class="product-art ${p.cat==='tea'?'tea':p.cat==='edible-oils'?'oil':''}"><span class="label">ILLUSTRATIVE PACKAGING</span><button class="wish" data-wish="${p.id}" aria-label="${wishlist.includes(p.id)?'Remove from':'Add to'} wishlist" aria-pressed="${wishlist.includes(p.id)}">${wishlist.includes(p.id)?'♥':'♡'}</button><a href="#product/${p.id}" aria-label="View ${p.name}" class="pack"><b>kedarmart</b><em>${p.cat==='coffee'?'Coffee':p.cat==='tea'?'Tea':'Mustard'}</em><small>${p.cat==='edible-oils'?'COLD PRESSED':'THE EVERYDAY COLLECTION'}</small></a></div>`}
function card(p){return `<article>${art(p)}<div class="product-info"><small>${names[p.cat].toUpperCase()}</small><h3><a href="#product/${p.id}">${p.name}</a></h3><div class="bottom"><span>Pricing coming soon</span><button data-add="${p.id}">Add to bag +</button></div></div></article>`}
function grid(list){return `<div class="products">${list.map(card).join('')}</div>`}
function title(k,h,extra=''){return `<div class="section-title"><div><span class="eyebrow">${k}</span><h2>${h}</h2></div>${extra}</div>`}
function newsletter(){return `<section class="newsletter"><div><span class="eyebrow">A LITTLE GOODNESS IN YOUR INBOX</span><h2>Stay in the everyday loop.</h2><p>Discover our evolving product world.</p></div><form id="newsletter"><label class="sr-only" for="news-email" style="position:absolute;clip:rect(0,0,0,0)">Email address</label><input id="news-email" type="email" required placeholder="Your email address"><button class="btn">Keep me updated ↗</button></form></section>`}
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">THE KEDARMART EVERYDAY COLLECTION</span><h1>Everyday rituals.<br><i>Extraordinary</i><br>little moments.</h1><p>From your first cup to your favourite meal. Discover thoughtfully selected coffee, tea and kitchen essentials, all in one place.</p><div class="hero-actions"><a class="btn" href="#shop">Find your everyday favourites <span aria-hidden="true">&nearr;</span></a><a class="textlink" href="#about">Meet Kedarmart</a></div><div class="hero-foot"><span>01 / Coffee</span><span>02 / Tea</span><span>03 / Edible oils</span></div></div><div class="hero-visual"><div class="hero-image" role="img" aria-label="A warm cup of coffee"><span class="image-note">THE BEAUTY OF A DAILY RITUAL</span></div><a class="hero-inset" href="#tea"><img src="${images.tea}" alt="A comforting cup of tea"><span>A pause, just for you. <b>Explore tea &nearr;</b></span></a><div class="hero-seal" aria-hidden="true"><span>THOUGHTFULLY</span><b>k.</b><span>SELECTED</span></div><span class="visual-caption">YOUR NEEDS, OUR COMMITMENT</span></div></section><div class="strip"><span>◇ QUALITY AT HEART</span><span>♧ BUILT ON TRUST</span><span>◌ VALUE FOR EVERYDAY</span><span>↗ CONVENIENCE IN MIND</span></div><section class="section">${title('FIND YOUR EVERYDAY','A world of good choices.','<a class="textlink" href="#shop">Explore all products ↗</a>')}<div class="categories">${[['coffee','Coffee','For your daily coffee ritual',images.coffee],['tea','Tea','Make time for your cup',images.tea],['edible-oils','Edible oils','Essentials for your kitchen',images.oil]].map(([id,n,s,i])=>`<a href="#${id}" class="category"><img src="${i}" alt="${n} collection" loading="lazy"><div><div style="position:static;display:block"><h3>${n}</h3><small>${s}</small></div><span>↗</span></div></a>`).join('')}</div></section><section class="section" style="padding-top:15px">${title('THE EVERYDAY EDIT','Discover your next favourite.','<a class="textlink" href="#shop">View all ↗</a>')}<p style="margin-top:-20px;margin-bottom:28px;font-size:11px">Best sellers will appear here when customer purchase data is available. Explore our featured selection.</p>${grid(products.slice(0,4))}</section>${[['coffee','YOUR MORNING, REIMAGINED','A moment. A cup. A fresh start.','From premium instant coffee to Arabica + Robusta blends and cappuccino premix. Discover your everyday coffee ritual.',images.coffee],['tea','PAUSE. POUR. ENJOY.','There’s always time for tea.','Explore Strong Premium CTC Tea, Premium CTC Blend, Premium Masala Tea and Green Tea.',images.tea],['edible-oils','FROM OUR PRODUCT WORLD','Good food starts with the essentials.','Discover our locally manufactured Premium Cold Pressed Mustard Oil.',images.oil]].map(([id,e,h,p,img])=>`<section class="feature"><img src="${img}" alt="${names[id]} ingredients" loading="lazy"><div><span class="eyebrow">${e}</span><h2>${h}</h2><p>${p}</p><a class="btn light" href="#${id}">Explore ${names[id].toLowerCase()} ↗</a></div></section>`).join('')}<section class="values">${[['◇','Quality','We work towards selecting and developing products that meet appropriate quality and regulatory requirements.'],['♧','Trust','Transparency, responsible business practices and relationships that last.'],['◌','Value','The right balance between quality, usefulness, reliability and affordability.'],['↗','Convenience','Making it easier to discover and purchase products for everyday needs.']].map(([s,h,p])=>`<div><span class="symbol">${s}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</section><section class="section">${title('OUR OWN BRANDS','Thoughtful products. Meaningful identities.')}<p>We believe that a strong business is built not only by selling products, but also by building brands. Our focus: Quality • Identity • Value • Trust.</p><a class="textlink" href="#brands">Discover our approach ↗</a></section><section class="section story"><img src="${images.story}" alt="A peaceful green landscape" loading="lazy"><div><span class="eyebrow">ROOTED IN A SIMPLE IDEA</span><h2>Good products should be easier to find, trust and buy.</h2><p>Kedarkhand Global Ventures brings together a thoughtfully selected range of our own brands and products from trusted manufacturers and established brands.</p><p>Through Kedarmart.com, we are building a diverse product ecosystem that connects brands, products and customers under one roof.</p><a class="btn light" href="#about">Get to know us ↗</a></div></section><section class="section" style="text-align:center;background:#efeee5"><span class="eyebrow">CUSTOMER VOICES</span><h2>Your experience matters.</h2><p>Customer reviews will be published when available.<br>Have a question about our products? We’re here to help.</p><a class="textlink" href="#contact">Get in touch ↗</a></section>${newsletter()}`}
function catalog(cat='all',q=''){let list=products.filter(p=>(cat==='all'||p.cat===cat)&&(`${p.name} ${p.desc}`.toLowerCase().includes(q.toLowerCase())));return `<section class="page"><span class="eyebrow">OUR PRODUCT WORLD</span><h1>${q?'Search results':cat==='all'?'Made for your everyday.':names[cat]}</h1><p>Different products. Meaningful brands. One convenient destination.</p><div class="filters">${[['shop','All products'],['coffee','Coffee'],['tea','Tea'],['edible-oils','Edible oils']].map(([r,n])=>`<a class="${(cat==='all'&&r==='shop')||cat===r?'active':''}" href="#${r}">${n}</a>`).join('')}</div><p>${list.length} products · Catalog preview — prices and pack sizes pending confirmation.</p>${list.length?grid(list):'<div class="empty">No products match your search. Try coffee, tea or oil.</div>'}</section>`}
function about(){return `<section class="page narrow"><span class="eyebrow">KEDARKHAND GLOBAL VENTURES</span><h1>Your Needs,<br><i>Our Commitment.</i></h1><h2>Who we are</h2><p>Kedarkhand Global Ventures is a growing consumer products and e-commerce company built around a simple idea: Good products should be easier to find, trust and buy.</p><p>We bring together a thoughtfully selected range of our own brands and products from trusted manufacturers and established brands, creating a convenient destination for everyday needs.</p><p>Through our online platform Kedarmart.com, we are building a diverse product ecosystem that connects brands, products and customers under one roof.</p><p>From everyday essentials to food and beverages, our vision is to make online shopping more convenient while giving customers access to products that combine quality, value and reliability.</p><h2>Our journey</h2><p>Our journey began with the vision of creating a business that goes beyond selling a single product or operating in a single category. We wanted to build a platform where different products, brands and everyday essentials could come together.</p><p>That vision led to Kedarkhand Global Ventures and our e-commerce platform, Kedarmart.com.</p><p>Today, we are building our product portfolio step by step, with a long-term focus on creating brands that customers can recognize, trust and return to.</p><h2>Kedarmart.com</h2><p>Our aim is to create a convenient online destination where customers can discover products across multiple categories.</p><h3>Our Own Brands</h3><p>Products developed and marketed by Kedarkhand Global Ventures.</p><h3>Trusted Brands</h3><p>Products sourced from reliable manufacturers, suppliers and established brands.</p><h3>Everyday Essentials</h3><p>Products selected around the changing needs of modern customers.</p><h2>Our product world</h2><p>We are building our portfolio across carefully selected categories, including Edible Oils and Tea & Coffee. Our portfolio will continue to evolve as we discover new products, categories and opportunities.</p><h2>Our vision</h2><p>To build a trusted destination where quality products and meaningful brands come together to meet everyday needs.</p><h2>Our mission</h2><p>To discover, develop and deliver products that add value to everyday life.</p><h2>Our promise</h2><p>We don't want to be just another online store.</p><h3>Continuous improvement</h3><p>We continuously work to improve our products, service and customer experience.</p><a class="btn" href="#shop">Discover our products ↗</a></section>`}
function brands(){return `<section class="page narrow"><span class="eyebrow">OUR OWN BRANDS</span><h1>Built with identity.<br>Guided by trust.</h1><p>We believe that a strong business is built not only by selling products, but also by building brands.</p><p>Kedarkhand Global Ventures is developing its own brands with a focus on:</p><h2>Quality • Identity • Value • Trust</h2><p>Our brands are designed to offer customers products with a clear identity and a consistent experience.</p><div class="notice">Our brand portfolio is being developed. Individual brand identities and product packaging will be shared when confirmed.</div><p><a class="btn" href="#shop">Explore the product world ↗</a></p></section>`}
function contact(){return `<section class="page narrow"><span class="eyebrow">LET’S CONNECT</span><h1>Here for your everyday.</h1><h2>Kedarkhand Global Ventures</h2><p>Your Needs, Our Commitment</p><p>Saheed Dal Bahadur Marg,<br>Near Big Sky Solar<br>Kaulagarh, Canal Road,<br>Dehradun, Uttarakhand<br>Pin 248003</p><p>GST No: 05AUSPC5607K1ZG</p><p>Email: <a class="textlink" href="mailto:poojachhetri2588@gmail.com">poojachhetri2588@gmail.com</a></p><p>E-commerce platform: Kedarmart.com<br>Domain supplied in company information: kadarmart.com</p><a class="btn" href="mailto:poojachhetri2588@gmail.com?subject=Kedarmart%20enquiry">Email our team ↗</a></section>`}
function product(id){const p=products.find(p=>p.id===id);if(!p)return `<section class="page empty"><h2>Product not found</h2><a href="#shop" class="btn">Explore products</a></section>`;return `<section class="page"><p><a href="#shop">Shop</a> / <a href="#${p.cat}">${names[p.cat]}</a> / ${p.name}</p><div class="detail">${art(p)}<div><span class="eyebrow">${names[p.cat]}</span><h1 style="font-size:44px">${p.name}</h1><p>${p.desc}</p><p>Pricing coming soon</p><label for="variant">Product options</label><select id="variant" disabled><option>${p.variant}</option></select><div class="notice">Catalog preview. Packaging is illustrative. Final product information, pricing and availability will be confirmed by our team.</div><button class="btn" data-add="${p.id}">Add to bag +</button><button class="btn light" data-buy="${p.id}">Enquire now ↗</button><p>Your bag is saved on this device for an availability enquiry.</p><h3>Product reviews</h3><p>No customer reviews yet.</p><a class="textlink" href="mailto:poojachhetri2588@gmail.com?subject=${encodeURIComponent('Product feedback: '+p.name)}">Share feedback by email ↗</a></div></div></section>`}
function cartPage(){const list=products.filter(p=>cart[p.id]);return `<section class="page narrow"><span class="eyebrow">YOUR EVERYDAY SELECTION</span><h1>Your bag.</h1>${list.length?`<p>Saved for your availability enquiry. Prices and variants are pending confirmation.</p>${list.map(p=>`<div class="cart-row"><div><a href="#product/${p.id}">${p.name}</a><p>Pricing coming soon</p></div><input type="number" min="1" max="99" value="${cart[p.id]}" data-qty="${p.id}" aria-label="Quantity for ${p.name}"><button data-remove="${p.id}" class="btn light" style="padding:9px">Remove</button></div>`).join('')}<p>Total: pending confirmed pricing</p><a href="#checkout" class="btn">Review enquiry ↗</a>`:'<div class="empty"><h2>A little room for goodness.</h2><p>Your bag is currently empty.</p><a class="btn" href="#shop">Explore products ↗</a></div>'}</section>`}
function checkout(){return `<section class="page narrow"><span class="eyebrow">REVIEW YOUR SELECTION</span><h1>Availability enquiry.</h1><div class="notice">Checkout and online payment are not active. This form opens an email enquiry; it does not place an order or charge you. Our team will confirm pricing, variants, shipping and availability.</div>${Object.keys(cart).length?`<p>${products.filter(p=>cart[p.id]).map(p=>`${p.name} × ${cart[p.id]}`).join('<br>')}</p><form id="enquiry"><div class="form-grid"><label>Name<input name="name" required autocomplete="name"></label><label>Email<input name="email" required type="email" autocomplete="email"></label><label class="wide">City / delivery postcode<input name="location" required></label><label class="wide">Questions or preferred product options<textarea name="message" rows="4"></textarea></label></div><button class="btn">Open email enquiry ↗</button></form>`:'<p>Your bag is empty. <a class="textlink" href="#shop">Explore products</a></p>'}</section>`}
function account(){return `<section class="page narrow"><span class="eyebrow">MY ACCOUNT</span><h1>Your everyday space.</h1><div class="notice">Customer login, registration and address management will be available when secure account services are connected. No password or personal account data is collected by this preview.</div><p>Your wishlist and bag are saved on this device.</p><a class="btn" href="#wishlist">View wishlist</a> <a class="btn light" href="#orders">Order information</a></section>`}
const policies={privacy:['Privacy policy','This storefront stores your bag and wishlist in your browser on this device. It does not create a customer account or transmit checkout data to a server. Availability enquiries are sent through your own email application when you choose to send them.','Third-party image and font services are used to display the site. A complete company privacy policy will be published before customer account and online ordering services launch.'],terms:['Terms & conditions','This is a catalog preview of the Kedarmart product portfolio. Product packaging is illustrative; pricing, pack sizes, variants and availability are pending confirmation. Adding a product to your bag does not constitute an order.','Commercial terms will be confirmed by Kedarkhand Global Ventures before a purchase. Contact our team for product information.'],shipping:['Shipping policy','Delivery coverage, charges and delivery timeframes have not yet been provided. Please contact our team to confirm shipping availability for your location before purchasing.','A complete shipping policy will be published before online ordering launches.'],returns:['Return & refund policy','Return eligibility, timeframes and refund terms have not yet been provided. Please contact our team for confirmed terms before purchasing.','This preview does not take payments or place orders. A complete return and refund policy will be published before online ordering launches.']};
function render(){const route=location.hash.slice(1)||'home';document.title=`${route==='home'?'Your Needs, Our Commitment':route.startsWith('product/')?'Product details':route.replace(/-/g,' ')} | Kedarmart`;if(route==='home')app.innerHTML=home();else if(['shop','all-products','coffee','tea','edible-oils'].includes(route))app.innerHTML=catalog(['shop','all-products'].includes(route)?'all':route);else if(route.startsWith('product/'))app.innerHTML=product(route.split('/')[1]);else if(route==='about')app.innerHTML=about();else if(route==='brands')app.innerHTML=brands();else if(route==='contact')app.innerHTML=contact();else if(route==='cart')app.innerHTML=cartPage();else if(route==='checkout')app.innerHTML=checkout();else if(route==='account')app.innerHTML=account();else if(route==='wishlist')app.innerHTML=`<section class="page"><span class="eyebrow">SAVE A LITTLE GOODNESS</span><h1>Your wishlist.</h1>${wishlist.length?grid(products.filter(p=>wishlist.includes(p.id))):'<div class="empty"><p>No favourites yet. Tap the heart on a product to save it.</p><a class="btn" href="#shop">Explore products ↗</a></div>'}</section>`;else if(route==='orders')app.innerHTML='<section class="page narrow"><span class="eyebrow">ORDERS</span><h1>Order history & tracking.</h1><p>No orders have been placed through this storefront. Online ordering and tracking are pending connection to an order service.</p><a class="btn" href="#contact">Contact us about an order ↗</a></section>';else if(policies[route])app.innerHTML=`<section class="page narrow"><span class="eyebrow">CUSTOMER INFORMATION</span><h1>${policies[route][0]}</h1>${policies[route].slice(1).map(p=>`<p>${p}</p>`).join('')}<a class="textlink" href="#contact">Contact Kedarkhand Global Ventures ↗</a></section>`;else app.innerHTML='<section class="page empty"><h1>Page not found</h1><a class="btn" href="#home">Return home</a></section>';save()}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add],[data-buy]');if(add){const id=add.dataset.add||add.dataset.buy;if(!products.some(p=>p.id===id))return;cart[id]=Math.min(99,(cart[id]||0)+1);save();if(add.dataset.buy)location.hash='checkout';else toast('Added to your enquiry bag')}const w=e.target.closest('[data-wish]');if(w){const id=w.dataset.wish;wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];save();w.textContent=wishlist.includes(id)?'♥':'♡';w.setAttribute('aria-pressed',wishlist.includes(id));w.setAttribute('aria-label',(wishlist.includes(id)?'Remove from':'Add to')+' wishlist');if(location.hash==='#wishlist')render()}const r=e.target.closest('[data-remove]');if(r){delete cart[r.dataset.remove];save();render()}});
document.addEventListener('change',e=>{if(e.target.dataset.qty){cart[e.target.dataset.qty]=Math.max(1,Math.min(99,Number(e.target.value)||1));save();render()}});
document.querySelector('#search-toggle').onclick=()=>{const s=document.querySelector('#searchbar');s.hidden=!s.hidden;if(!s.hidden)document.querySelector('#search').focus()};document.querySelector('#search').addEventListener('input',e=>{app.innerHTML=catalog('all',e.target.value)});
document.addEventListener('submit',e=>{if(e.target.id==='newsletter'){e.preventDefault();const email=document.querySelector('#news-email').value;location.href='mailto:poojachhetri2588@gmail.com?subject=Newsletter%20interest&body='+encodeURIComponent('Please keep me updated about Kedarmart. My email: '+email);toast('Email draft opened. Send it to register your interest.')}if(e.target.id==='enquiry'){e.preventDefault();const f=new FormData(e.target);const body=`Name: ${f.get('name')}\nEmail: ${f.get('email')}\nLocation: ${f.get('location')}\n\nProduct enquiry:\n${products.filter(p=>cart[p.id]).map(p=>`${p.name} × ${cart[p.id]}`).join('\n')}\n\n${f.get('message')}\n\nPlease confirm pricing, available variants, shipping and availability.`;location.href='mailto:poojachhetri2588@gmail.com?subject=Kedarmart%20product%20enquiry&body='+encodeURIComponent(body);toast('Email draft opened. No order has been placed.')}});
window.addEventListener('hashchange',()=>{document.querySelector('#searchbar').hidden=true;document.querySelector('#search').value='';render();window.scrollTo({top:0,behavior:'instant'})});render();
